import React, { useEffect, useMemo, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import api from '../../lib/api';

export default function AdminOrderDetail(){
  const { id } = useParams();
  const nav = useNavigate();
  const [order, setOrder] = useState(null);
  const [status, setStatus] = useState('pending');
  const [loading, setLoading] = useState(false);
  const allowed = ['pending','paid','processing','shipped','canceled'];

  async function load(){
    setLoading(true);
    try{
      const r = await api.get(`/admin/orders/${id}`);
      const o = r.data;
      // Normalize items: could be JSON string
      if (o && typeof o.items === 'string'){
        try { o.items = JSON.parse(o.items); } catch {}
      }
      setOrder(o);
      setStatus(o?.status || 'pending');
    }catch(err){
      console.error('Load order failed', err);
      const s = err.response?.status;
      if (s === 401 || s === 403) alert('Akses admin diperlukan.');
    }finally{
      setLoading(false);
    }
  }

  async function save(){
    try{
      const r = await api.patch(`/admin/orders/${id}`, { status });
      setOrder(r.data);
      alert('Status tersimpan');
    }catch(err){
      console.error('Update status failed', err);
      const msg = err.response?.data?.error || 'Gagal menyimpan status';
      alert(msg);
    }
  }

  useEffect(()=>{ load(); },[id]);

  const totals = useMemo(()=>{
    if (!order || !Array.isArray(order.items)) return { qty: 0, amount: order?.total_amount || 0 };
    const qty = order.items.reduce((a,b)=> a + (b.quantity||0), 0);
    const amount = order.items.reduce((a,b)=> a + (b.quantity||0)*(b.price||0), 0);
    return { qty, amount };
  }, [order]);

  return (
    <div style={{padding:20}}>
      <header style={{display:'flex',justifyContent:'space-between',alignItems:'center',marginBottom:16}}>
        <strong>Admin</strong>
        <nav style={{display:'flex',gap:12}}>
          <a href="/admin/products">Products</a>
          <a href="/admin/orders">Orders</a>
          <a href="#" onClick={(e)=>{e.preventDefault(); localStorage.removeItem('hr_token'); localStorage.removeItem('hr_user'); window.location.href='/admin/login';}}>Logout</a>
        </nav>
      </header>

      <button onClick={()=> nav('/admin/orders')} style={{marginBottom:12}}>← Kembali</button>
      <h2>Order Detail</h2>
      {loading && <div>Loading...</div>}
      {!loading && order && (
        <div>
          <div style={{marginBottom:12}}>
            <div><strong>Order:</strong> {order.order_number}</div>
            <div><strong>Pembeli:</strong> {order.user ? `${order.user.name} (${order.user.email})` : '-'}</div>
            <div><strong>Dibuat:</strong> {order.created_at}</div>
          </div>

          <div style={{marginBottom:12}}>
            <label>Status: </label>
            <select value={status} onChange={e=>setStatus(e.target.value)}>
              {allowed.map(s => <option key={s} value={s}>{s}</option>)}
            </select>
            <button onClick={save} style={{marginLeft:8}}>Simpan</button>
          </div>

          <table border="1" cellPadding={8} style={{width:'100%', marginTop:8}}>
            <thead>
              <tr>
                <th>#</th>
                <th>Nama</th>
                <th>Harga</th>
                <th>Qty</th>
                <th>Subtotal</th>
              </tr>
            </thead>
            <tbody>
              {(order.items||[]).map((it, idx) => (
                <tr key={idx}>
                  <td>{idx+1}</td>
                  <td>{it.name}</td>
                  <td>{it.price}</td>
                  <td>{it.quantity}</td>
                  <td>{(it.price||0) * (it.quantity||0)}</td>
                </tr>
              ))}
            </tbody>
          </table>
          <div style={{marginTop:12, textAlign:'right'}}>
            <div><strong>Total Qty:</strong> {totals.qty}</div>
            <div><strong>Total Amount:</strong> {totals.amount}</div>
          </div>
        </div>
      )}
    </div>
  );
}
